/* BabyPlan v2：纯本机交互原型。无网络接口、真实账号、通知或媒体上传。 */
(() => {
  'use strict';
  const content = window.BABYPLAN_CONTENT;
  const $ = (q, parent = document) => parent.querySelector(q);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
  const icons = () => window.lucide?.createIcons();
  const app = $('#app'), dialog = $('#sheet');
  const surface = new URLSearchParams(location.search).get('surface') || 'mobile';
  const embedded = new URLSearchParams(location.search).get('embed') === '1';
  const storageKey = 'babyplan-design-v2.0';
  const today = '2026-11-13';
  const kinds = {movement:['运动','circle-dot'],explore:['探索','shapes'],reading:['共读','book-open'],english:['英语','message-circle'], 'child-led':['孩子主导','heart'],calm:['安静收尾','moon']};
  const blocks = {before:['晚饭前','16:00～17:15','sun'],after:['晚饭后','18:30～19:20','sunset'],bedtime:['睡前','跟着原有睡前节奏','moon']};
  const labels = ['周五','周六','周日','周一','周二','周三','周四'];
  const cards = Object.fromEntries(content.cards.map(c => [c.id,c]));
  const initial = () => ({records:{},replacements:{},modes:{},memories:[{id:'example-quote',type:'quote',text:'“球球，给妈妈。”',date:'2026-11-11',author:'另一位家长',example:true},{id:'example-story',type:'story',text:'今天还是选了最熟悉的那本书。翻到喜欢的一页，指了又指，我们就多看了一会儿。',date:'2026-11-10',author:'我',example:true}],measurements:[],observations:{},bookNotes:{},reminder:false,reminderTime:'16:00',admin:{status:'draft',title:'把大软球滚给你',opening:'球来找你啦。',note:'',checks:[],releases:[]}});
  let state=initial();
  try {const stored=JSON.parse(localStorage.getItem(storageKey)); if(stored?.records && stored?.admin)state={...state,...stored};}catch(_){ /* 隔离损坏的演示存储，不影响预览入口。 */ }
  let day=0, scenario='normal', member='me', filter='all', query='', libraryTab='activities', stage='m18_23', role='editor', toastTimer, selectedItem=null, lastFocus=null, memoryFilter='all';
  if(embedded)document.body.classList.add('embed');
  if(surface !== 'mobile'){$('#workspace').classList.add('desktop');$('#design-caption').hidden=true;}
  if(surface==='admin')$('#workspace').classList.add('admin');
  document.querySelectorAll('[data-surface]').forEach(a=>a.classList.toggle('active',a.dataset.surface===surface));

  function commit(change){
    const next=structuredClone(state); change(next);
    try{localStorage.setItem(storageKey,JSON.stringify(next));state=next;return true;}
    catch(_){toast('没有保存成功，可能是浏览器存储空间不足。刚才的输入仍保留。');return false;}
  }
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
  function route(){return (location.hash.slice(1)|| (surface==='admin'?'library':'today')).split('/');}
  function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
  function closeSheet(){dialog.close();lastFocus?.focus?.();}
  function sheet(title,body,onSubmit){
    lastFocus=document.activeElement;
    dialog.innerHTML=`<div class="sheet-header"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭">${icon('x')}</button></div>${body}`;
    icons();if(!dialog.open)dialog.showModal();
    const form=$('form',dialog);if(form)form.addEventListener('submit',e=>{e.preventDefault();onSubmit?.(new FormData(form),form);});
  }
  function dateAt(index){return `2026-11-${13+index}`;}
  function dayItems(index=day){
    return content.week.days[index].items.map(item=>({...item,cardId:state.replacements[item.id]||item.cardId,minutes:state.modes[index]==='lite'&&!state.records[item.id]?5:item.minutes})).filter(item=>state.modes[index]!=='lite'||['movement','explore','reading','english'].includes(item.kind)||state.records[item.id]);
  }
  function itemById(id){return content.week.days.flatMap((d,index)=>d.items.map(item=>({...item,dayIndex:index,cardId:state.replacements[item.id]||item.cardId,minutes:state.modes[index]==='lite'&&!state.records[item.id]?5:item.minutes}))).find(i=>i.id===id);}
  function cardState(id){const r=state.records[id];return r?(r.status==='played'?'已一起玩':'今天先跳过'):'还没记录';}
  function scene(){return '<div class="scene" aria-hidden="true"><div class="scene-shadow"></div><div class="book"></div><div class="ball"></div><span class="star">✳</span><div class="twig"></div></div>';}
  function empty(title,description,button='',action='retry'){return `<div class="empty">${icon('sprout')}<h2>${title}</h2><p>${description}</p>${button?`<button class="primary" data-action="${action}">${button}</button>`:''}</div>`;}
  function notice(){return scenario==='offline'?`<div class="status-note">${icon('wifi-off')}当前离线，下载过的玩法仍可查看。</div>`:'';}
  function weekStrip(){return `<nav class="week-strip" aria-label="七天安排">${labels.map((label,i)=>`<button class="day-button ${i===day?'active':''} ${i===0?'today':''}" data-action="day" data-value="${i}" aria-pressed="${i===day}"><span>${i===0?'今天':label}</span><b>${13+i}</b></button>`).join('')}</nav>`;}
  function thumbnail(card){return `<span class="thumb ${card.kind}">${icon(kinds[card.kind][1])}</span>`;}
  function itemRow(item){const c=cards[item.cardId];return `<button class="activity-row" data-action="open-item" data-id="${item.id}">${thumbnail(c)}<span class="row-title"><strong>${esc(c.title)}</strong><small>${item.minutes}分钟可拆分 · ${cardState(item.id)}</small></span>${icon(state.records[item.id]?'check':'chevron-right')}</button>`;}
  function blockList(allOpen=false){return Object.entries(blocks).map(([key,[title,time,i]])=>{
    const items=dayItems().filter(x=>x.block===key);if(!items.length)return '';
    return `<details class="plan-section" ${allOpen||key==='before'?'open':''}><summary><span class="slot-badge">${icon(i)}</span><span class="slot-name"><strong>${title}</strong><small>${time}</small></span><span class="budget">约${items.reduce((a,x)=>a+x.minutes,0)}分</span>${icon('chevron-down')}</summary><div class="plan-items">${items.map(itemRow).join('')}</div></details>`;
  }).join('');}
  function title(text,sub){return `<div class="page-intro"><h1>${text}</h1>${sub?`<p>${sub}</p>`:''}</div>`;}
  function heading(text,back='today',extra=''){return `<div class="view-heading"><button class="icon-button" data-action="go" data-path="${back}" aria-label="返回">${icon('arrow-left')}</button><h1>${text}</h1>${extra}</div>`;}
  function todayView(){
    if(scenario==='error')return title('今天，一起玩点什么？','18～23月 · 陪着看、陪着做就很好')+empty('暂时没取到安排','这不代表今天没有内容。已有记录仍在本机。','重新加载');
    if(scenario==='empty')return title('今天，一起玩点什么？','18～23月')+empty('今天还没有可用安排','正式App会从审核后的内容中准备；这里可先看看活动。','去看看活动','discover');
    const items=dayItems(), next=items.find(i=>!state.records[i.id]), c=next?cards[next.cardId]:null;
    return `<div class="page-intro"><div class="date">11月${13+day}日 · 星期${['五','六','日','一','二','三','四'][day]} <span class="pill neutral">18～23月</span></div><h1>${day?'这一天，也一起慢慢来。':'今天，一起玩点什么？'}</h1><p>跟着宝宝的兴趣，玩一会儿就很好。</p></div>${weekStrip()}${notice()}${c?`<section class="hero-card"><div class="hero-meta"><span>先从这一项开始</span><span>${kinds[c.kind][0]} · 约${next.minutes}分钟</span></div>${scene()}<h2>${esc(c.title)}</h2><p>${esc(c.materials[0]||'不用道具，面对面就能开始')}</p><button class="primary" data-action="open-item" data-id="${next.id}">看看怎么玩 ${icon('arrow-up-right')}</button></section>`:empty('今天的陪伴，照自己的节奏','已经留下记录。想再玩时，可以从发现里挑一项。','再找个玩法','discover')}<div class="nudge">${icon('heart')}时间只是参考，想停的时候就停。</div><div class="section-title"><h2>一天的轻松节奏</h2><button class="text-button" data-action="mode">${state.modes[day]==='lite'?'恢复完整安排':'今天忙一点'} ${icon('arrow-right')}</button></div>${blockList()}<button class="text-button block-button" data-action="go" data-path="week">看看接下来一周 ${icon('arrow-right')}</button><p class="small muted" style="margin-top:12px">晚饭与洗漱留给生活本身。没玩到的，明天不补作业。</p>`;
  }
  function detailContent(c,compact=false){return `${compact?'':`<div class="detail-art">${scene()}</div>`}<div class="material-box"><h3>${icon('shopping-bag')}拿好这些就能开始</h3><p>${c.materials.length?c.materials.map(esc).join(' · '):'不用道具。找一个舒服、安全的位置。'}</p></div><h2 style="font-size:1.1rem;margin-top:22px">这样玩，慢慢来</h2><ol class="steps">${c.steps.map((s,i)=>`<li><span class="step-no">${i+1}</span><span>${esc(s)}</span></li>`).join('')}</ol><div class="quote-box"><span class="eyebrow">开口可以这样说</span><blockquote>“${esc(c.dialogue.opening)}”</blockquote></div>${compact?'':`<div class="response-options"><details><summary>宝宝跟着玩时，怎么接？</summary><p>${esc(c.dialogue.engaged)}</p></details><details><summary>宝宝只是看看，也没关系</summary><p>${esc(c.dialogue.observing)}</p></details><details><summary>宝宝想停了，就这样结束</summary><p>${esc(c.dialogue.stopping)}</p></details></div><div class="english-card"><span class="eyebrow">顺口说一句 · 不要求跟读</span><strong lang="en">${esc(c.english.phrase)}</strong><p>${esc(c.english.meaning)}</p><p class="muted" style="margin-top:8px">${esc(c.english.when)}</p></div><div class="response-options"><details><summary>更容易一点 / 想再试一步</summary><p><strong>更容易：</strong>${esc(c.easier)}</p><p><strong>下一步：</strong>${esc(c.next)}</p></details></div>`}<div class="safety"><strong>陪玩时留意</strong><br>${esc(c.safety)}</div>${compact?'':`<details class="small muted"><summary>内容依据与说明</summary><p style="padding-top:10px">原创活动候选，尚未完成专业审阅和家庭试玩。来源支持方向，不是这张卡的官方认证。</p>${c.sourceIds.map(id=>{const s=content.sources.find(x=>x.id===id);return `<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></p>`;}).join('')}</details>`}`;}
  function detailView(cardId,itemId){const c=cards[cardId]||cards.roll, item=itemId?itemById(itemId):null;
    return `${heading('一起玩一会儿',item?'today':'discover')}<div class="detail-title"><span class="pill">${kinds[c.kind][0]} · 18～23月</span><h1>${esc(c.title)}</h1><p>${esc(c.support)}</p></div>${notice()}${detailContent(c)}<div class="detail-actions"><button class="primary block-button" data-action="record" data-id="${item?.id||''}" data-card="${c.id}" ${item&&day>0?'disabled':''}>${icon('check')}${item&&day>0?'这一天还没到':item&&state.records[item.id]?'查看 / 修改记录':'一起玩了'}</button>${item&&day===0?`<div class="button-row"><button class="text-button" data-action="skip" data-id="${item.id}" data-card="${c.id}">今天先跳过</button><button class="text-button" data-action="replace" data-id="${item.id}">换一个玩法 ${icon('refresh-cw')}</button></div>`:''}${!item?'<p class="field-help">临时开展，记录到今天；不覆盖已有安排。</p>':''}</div>`;
  }
  function filteredCards(){return content.cards.filter(c=>(filter==='all'||c.kind===filter)&&(!query||c.title.includes(query)||c.support.includes(query)||c.materials.join('').includes(query)));}
  function libraryCards(){const list=filteredCards();return list.length?list.map(c=>`<button class="library-card" data-action="open-card" data-card="${c.id}">${thumbnail(c)}<span class="card-copy"><h3>${esc(c.title)}</h3><p>${esc(c.support)}</p><small>${kinds[c.kind][0]} · ${c.materials.length?'家中常见材料':'不用道具'}</small></span>${icon('chevron-right')}</button>`).join(''):empty('还没有找到这个玩法','试试“球”“书”或选择其他分类。');}
  function booksView(){return `<div class="notice-card">用已有的书就很好。具体版本尚未核实的书，先使用通用共读方法。</div><div class="book-grid">${content.books.map(b=>`<button class="book-card" data-action="book" data-id="${b.id}"><div class="book-cover">${icon('book-open')}<strong>${esc(b.title)}</strong><small>家中书目 · 文字占位</small></div><span>版本待核 · ${esc(state.bookNotes[b.id]||b.note)}</span></button>`).join('')}</div><button class="secondary block-button" style="margin-top:20px" data-action="open-card" data-card="page">用家里的书，先共读一页 ${icon('arrow-right')}</button>`;}
  function discoverView(){return `${title('发现一点新玩法','家里的书和小物件，就能开始。')}<div class="segmented"><button data-action="library-tab" data-value="activities" class="${libraryTab==='activities'?'active':''}" aria-pressed="${libraryTab==='activities'}">活动灵感</button><button data-action="library-tab" data-value="books" class="${libraryTab==='books'?'active':''}" aria-pressed="${libraryTab==='books'}">家中书架</button></div>${libraryTab==='books'?booksView():`<label class="search"><span class="screen-reader">搜索活动</span>${icon('search')}<input id="activity-search" placeholder="找一个玩法、一本书的灵感" value="${esc(query)}"></label><div class="chips">${[['all','全部'],...Object.entries(kinds).map(([id,v])=>[id,v[0]])].map(([id,label])=>`<button class="chip ${filter===id?'active':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div id="library-results" class="library-list">${libraryCards()}</div>`}`;}
  function stageView(){const guide=content.stageGuides.find(g=>g.ageBand===stage);return `${title('陪着长大，慢慢来','知道怎么支持，比记住多少指标更有用。')}<div class="chips">${content.ageBands.map(b=>`<button class="chip ${stage===b.id?'active':''}" data-action="stage-band" data-value="${b.id}" aria-pressed="${stage===b.id}">${b.label}</button>`).join('')}</div><div class="stage-banner"><span class="pill">${stage==='m18_23'?'当前推荐阶段':'阶段预览'}</span><h2>${guide.title}</h2><p>${guide.description}</p></div>${guide.focuses.map((f,i)=>`<button class="stage-focus" data-action="focus" data-id="${f.id}"><span class="stage-count">0${i+1}</span><div><span class="eyebrow">${f.domain}</span><h3 style="margin-top:5px">${f.title}</h3><p>${f.support}</p>${state.observations[f.id]?`<span class="pill" style="margin-top:10px">${esc(state.observations[f.id])}</span>`:''}</div>${icon('chevron-right')}</button>`).join('')}<p class="small muted" style="margin-top:22px">这里是支持建议，不是发育评分。玩过和掌握是两件事；没记过，也不代表不会。</p><button class="text-button block-button" data-action="concern">有些变化，我想和专业人员聊聊 ${icon('arrow-up-right')}</button>`;}
  function memoriesView(){const list=state.memories.filter(m=>memoryFilter==='all'||m.type===memoryFilter).sort((a,b)=>b.date.localeCompare(a.date));return `${title('把小小的今天，留下来','一句原话，一次尝试，一段一起长大的时光。')}<div class="button-row" style="margin-top:20px"><button class="primary" data-action="memory">${icon('plus')}记一个小瞬间</button><button class="secondary" data-action="go" data-path="measurements">${icon('ruler')}测量</button></div><div class="chips">${[['all','全部'],['quote','孩子原话'],['first','第一次'],['story','小故事']].map(([id,label])=>`<button class="chip ${memoryFilter===id?'active':''}" data-action="memory-filter" data-value="${id}" aria-pressed="${memoryFilter===id}">${label}</button>`).join('')}</div><div class="memory-list">${list.length?list.map(m=>`<article class="memory"><div class="memory-date">${m.date}${m.example?' · 虚构示例':''}</div><div class="memory-body"><span class="pill ${m.type==='quote'?'warm':''}">${{quote:'孩子原话',story:'小故事',first:'家长确认的第一次'}[m.type]}</span>${m.type==='quote'?`<blockquote>${esc(m.text)}</blockquote>`:`<p style="margin-top:12px">${esc(m.text)}</p>`}${m.photo?'<div class="photo-placeholder">'+icon('image')+'照片占位 · 尚未上传</div>':''}<footer><span>${esc(m.author)}记录</span><button class="text-button" data-action="memory" data-id="${m.id}">编辑</button></footer></div></article>`).join(''):empty('还没有这一类记录','不用每天记，有想留下的瞬间再写。')}</div>`;}
  function measurementsView(){return `${heading('测量小记','growth')}${title('看自己的变化','保存测量事实，首版不展示医学百分位。')}<button class="primary block-button" style="margin:20px 0" data-action="measurement">${icon('plus')}添加测量</button>${state.measurements.length?`${trend()}<table class="measurement-table"><caption class="screen-reader">本人测量明细</caption><thead><tr><th>日期</th><th>测量</th><th>方式 / 来源</th></tr></thead><tbody>${state.measurements.map(m=>`<tr><td>${esc(m.date)}</td><td>${m.value} ${m.kind==='height'?'cm':'kg'}</td><td>${esc(m.method)}<br><span class="muted">${esc(m.source)}</span></td></tr>`).join('')}</tbody></table>`:empty('还没有测量记录','先记下一次真实测量。只有自己的数据，才画自己的曲线。')}<p class="small muted" style="margin-top:20px">卧位身长与站立身高保留原测量方式。数值有疑问时，先核对记录或咨询儿保人员。</p>`;}
  function trend(){
    const groups=[['height','recumbent','卧位身长','cm'],['height','standing','站立身高','cm'],['weight','scale','体重','kg']];
    return groups.map(([kind,method,label,unit])=>{
      const localMethod={recumbent:'卧位身长',standing:'站立身高',scale:'体重秤'}[method];
      const values=state.measurements.filter(m=>m.kind===kind&&m.method===localMethod).sort((a,b)=>a.date.localeCompare(b.date));
      if(!values.length)return '';
      const pad=kind==='weight'?.5:1,min=Math.min(...values.map(m=>+m.value))-pad,max=Math.max(...values.map(m=>+m.value))+pad;
      const times=values.map(m=>Date.parse(m.date)),t0=Math.min(...times),t1=Math.max(...times);
      const pts=values.map((m,i)=>[45+(t1===t0?110:220*(times[i]-t0)/(t1-t0)),120-80*(m.value-min)/(max-min)]);
      return `<p class="small" style="margin-top:18px">本人${label}（${unit}）</p><svg class="trend" viewBox="0 0 320 160" role="img" aria-label="本人${label}记录，详细数值见下方表格"><text x="5" y="40">${max.toFixed(1)}</text><text x="5" y="123">${min.toFixed(1)}</text>${values.length>1?`<polyline points="${pts.map(p=>p.join(',')).join(' ')}"/>`:''}${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}<text x="45" y="150">${values[0].date.slice(5)}</text>${values.length>1?`<text x="238" y="150">${values.at(-1).date.slice(5)}</text>`:''}</svg>`;
    }).join('');
  }
  function settingsView(){return `${title('我们的小家庭','谁有空谁带，陪伴不用提前分工。')}<div class="setting-group"><div class="setting-row"><span class="avatar">我</span><div class="setting-text"><strong>我 · 家庭管理员</strong><small>演示账号</small></div></div><div class="setting-row"><span class="avatar">伴</span><div class="setting-text"><strong>另一位家长</strong><small>一起看安排、一起记成长</small></div></div><div class="setting-row"><div class="setting-text"><strong>邀请家人</strong><small>受邀成员共享本家庭资料</small></div><button data-action="invite">邀请 ${icon('arrow-up-right')}</button></div></div><div class="setting-group"><div class="setting-row"><div class="setting-text"><strong>每天提醒我一次</strong><small>${state.reminder?'已保存开启偏好 · 原型不发通知':'当前未开启 · 建议16:00附近'}</small></div><button data-action="reminder">${state.reminder?'调整':'设置'}</button></div><div class="setting-row"><div class="setting-text"><strong>孩子阶段</strong><small>18～23月 · 月龄估算，未填生日</small></div><button data-action="age">查看</button></div><div class="setting-row"><div class="setting-text"><strong>陪伴节奏</strong><small>16:00～20:00 · 晚饭17:30左右</small></div><button data-action="schedule-info">查看</button></div></div><div class="setting-group"><div class="setting-row"><div class="setting-text"><strong>导出我的记录</strong><small>当前浏览器的虚构演示数据</small></div><button data-action="export">导出</button></div><div class="setting-row"><div class="setting-text"><strong>设计与数据说明</strong><small>未接入真实家庭服务</small></div><button data-action="about">查看</button></div></div>`;}
  function weekView(){return `${surface==='mobile'?heading('接下来的一周'):''}${title('每天一点，熟悉地玩','系统准备好，你们按当天的状态选择。')}<div class="week-cards" style="margin-top:22px">${content.week.days.map((d,i)=>`<section class="week-card"><header><strong>11月${13+i}日 · ${labels[i]}</strong><span class="pill">${i?'已准备':'今天'}</span></header><h3>${d.theme}</h3><ul>${dayItems(i).map(item=>`<li>${esc(cards[item.cardId].title)}<span>${item.minutes}分</span></li>`).join('')}</ul><button class="text-button" data-action="day" data-value="${i}">查看这一天 ${icon('arrow-right')}</button></section>`).join('')}</div><p class="small muted" style="margin-top:22px">这是虚构的一周内容样本。预算可拆分，周末不自动加量。</p>`;}
  function startView(){return `<div class="onboarding">${scene()}<span class="eyebrow">WELCOME TO BABYPLAN</span><h1>小小的日常，<br>慢慢地长大。</h1><p>每天准备几个好开始的玩法，<br>剩下的时间，留给你和宝宝。</p><div class="material-box"><h3>先从现在的阶段开始</h3><p>18～23月 · 中英共读 · 家中常见材料</p></div><button class="primary block-button" data-action="go" data-path="today">进入演示家庭 ${icon('arrow-right')}</button><p class="field-help" style="margin-top:15px">正式App支持创建家庭或接受邀请；这里不收集账号、生日或真实家庭资料。</p></div>`;}
  function mobileShell(body,current){return `<header class="app-header"><a class="brand" href="#today"><span class="brand-mark">${icon('sprout')}</span>小芽 <small>BabyPlan</small></a><button class="icon-button" data-action="go" data-path="settings" aria-label="家庭与设置"><span class="avatar">${member==='me'?'我':'伴'}</span></button></header><main class="app-main">${body}</main><nav class="bottom-nav" aria-label="主要导航">${[['today','sun','今天'],['discover','compass','发现'],['stage','sprout','阶段'],['growth','heart','成长']].map(([id,i,label])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}</nav>`;}
  function desktopShell(body,current){const isAdmin=surface==='admin';const nav=isAdmin?[['library','layers','内容库'],['review','clipboard-check','审核'],['releases','package-check','发布记录'],['sources','library','来源']]:[['today','calendar-days','陪伴安排'],['books','book-open','家中书架'],['stage','sprout','阶段路线'],['growth','heart','成长时光'],['settings','users','家庭设置']];return `<aside class="desktop-sidebar"><a class="brand" href="#${isAdmin?'library':'today'}"><span class="brand-mark">${icon('sprout')}</span>小芽</a><nav aria-label="${isAdmin?'内容工作台':'家长区'}导航">${nav.map(([id,i,label])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-footer"><strong>${isAdmin?'内容工作台':'我们的小家庭'}</strong>${isAdmin?'让每张卡都能放心交到家长手里。':'一岁半的今天，也值得慢慢过。'}<br><br>虚构数据 · 本机交互预览</div></aside><main class="desktop-main"><div class="desktop-topline"><span>${isAdmin?'内容工作台 / 编辑与发布':'家庭空间 / 爸爸妈妈一起陪伴'}</span>${isAdmin?`<label class="button-row" style="font-size:.8rem">模拟角色 <select id="admin-role" aria-label="模拟内容角色" style="width:auto;min-height:42px;padding:7px 12px">${[['editor','内容编辑'],['reviewer','内容审阅'],['publisher','发布者'],['viewer','只读']].map(([v,l])=>`<option value="${v}" ${v===role?'selected':''}>${l}</option>`).join('')}</select></label>`:'<span>18～23月 · 演示家庭 <span class="avatar" style="margin-left:10px">我</span></span>'}</div>${body}</main>`;}
  function parentToday(){if(scenario==='error'||scenario==='empty')return todayView();const item=itemById(selectedItem)||dayItems()[0],c=cards[item.cardId];return `<div class="desktop-title"><div><h1>把今天的陪伴，准备好。</h1><p>11月${13+day}日 · ${labels[day]} · 六项可拆分的小小灵感</p></div><div class="button-row"><button class="secondary" data-action="go" data-path="week">${icon('calendar-days')}一周安排</button><button class="primary" data-action="mode">${state.modes[day]==='lite'?'恢复完整安排':'今天忙一点'}</button></div></div>${notice()}${weekStrip()}<div class="desktop-grid"><section>${blockList(true)}<p class="small muted">晚饭与洗漱不计入预算，不需要凑满时长。</p></section><aside class="right-detail"><span class="pill">${kinds[c.kind][0]} · 约${item.minutes}分钟</span><h2>${esc(c.title)}</h2><p class="small muted">${esc(c.support)}</p>${detailContent(c,true)}<button class="primary block-button" data-action="record" data-id="${item.id}" data-card="${c.id}" ${day?'disabled':''}>${icon('check')}${day?'未来安排可预览':'记下这次陪伴'}</button><button class="text-button block-button" data-action="replace" data-id="${item.id}">换一个玩法</button></aside></div>`;}
  function adminLibrary(){return `<div class="desktop-title"><div><h1>把好玩法，写得更好用。</h1><p>18～23月候选内容 · 24张原创卡 · 尚未正式发布</p></div><button class="primary" data-action="go" data-path="editor/roll">${icon('pencil')}编辑示例卡</button></div><p class="admin-intro">每张卡都有材料、步骤、四类回应和安全提示。角色权限与发布过程在本页模拟，不会修改正式服务。</p><table class="admin-table"><thead><tr><th>内容</th><th>类型</th><th>阶段</th><th>状态</th><th>操作</th></tr></thead><tbody>${content.cards.map(c=>`<tr><td><strong>${c.id==='roll'?esc(state.admin.title):c.title}</strong><small>${esc(c.support)}</small></td><td>${kinds[c.kind][0]}</td><td>18～23月</td><td><span class="pill ${c.id==='roll'?'warm':''}">${c.id==='roll'?adminStatus():'草稿候选'}</span></td><td><button class="text-button" data-action="${c.id==='roll'?'go':'open-card'}" ${c.id==='roll'?'data-path="editor/roll"':`data-card="${c.id}"`}>${c.id==='roll'?'编辑':'预览'} ${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table>`;}
  function adminStatus(){return {draft:'草稿',review:'待审核',approved:'审核通过',published:'已发布（模拟）',withdrawn:'已撤回（模拟）'}[state.admin.status];}
  function adminEditor(){return `<div class="desktop-title"><div><h1>把大软球滚给你</h1><p>活动编辑 · 修改后重新审核 · ${adminStatus()}</p></div><button class="secondary" data-action="go" data-path="library">返回内容库</button></div><div class="editor-grid"><section class="editor-form"><form id="admin-editor" class="form-grid"><label><span>活动标题</span><input name="title" maxlength="60" required value="${esc(state.admin.title)}" ${role!=='editor'?'disabled':''}></label><label><span>开场话术</span><textarea name="opening" required maxlength="300" ${role!=='editor'?'disabled':''}>${esc(state.admin.opening)}</textarea></label><label><span>本次修改说明</span><textarea name="note" maxlength="500" ${role!=='editor'?'disabled':''} placeholder="让家长更容易理解的改动…">${esc(state.admin.note)}</textarea></label><p class="small muted">完整结构含3步玩法、安全提示、年龄理由、来源；本原型演示标题与话术修订，其余字段沿用候选卡。</p><div class="button-row"><button class="secondary" type="submit" ${role!=='editor'?'disabled':''}>保存草稿</button><button class="primary" type="button" data-action="submit-review" ${role!=='editor'||!['draft','withdrawn'].includes(state.admin.status)?'disabled':''}>送审 ${icon('arrow-right')}</button></div><p class="field-help">${role!=='editor'?'当前角色不能编辑；可在顶部演示面板切换角色。':'送审前会保存当前表单，不会丢掉未保存修改。'}</p></form></section><aside class="right-detail"><span class="eyebrow">家长卡片预览</span><h2 id="draft-preview-title">${esc(state.admin.title)}</h2><div class="quote-box"><span class="eyebrow">开口可以这样说</span><blockquote id="draft-preview-opening">“${esc(state.admin.opening)}”</blockquote></div>${detailContent(cards.roll,true).replace(/<div class="quote-box">[\s\S]*?<\/div>/,'')}</aside></div>`;}
  function reviewView(){return `<div class="desktop-title"><div><h1>每一句，都值得再看一遍。</h1><p>审核不等于发布 · 当前${adminStatus()}</p></div></div><div class="editor-grid"><section class="review-card"><span class="pill">当前候选</span><h2 style="margin-top:15px">${esc(state.admin.title)}</h2><div class="quote-box"><span class="eyebrow">拟使用的开场话术</span><blockquote>“${esc(state.admin.opening)}”</blockquote></div><h3>修改说明</h3><p class="small muted" style="margin-top:8px">${esc(state.admin.note||'尚未填写修改说明。')}</p><div class="material-box"><h3>修订前</h3><p>标题：把大软球滚给你<br>话术：球来找你啦。</p></div><p class="small muted">来源依据是方向参考；一张卡的适龄、安全与语言仍要逐项核对。</p></section><section class="review-card"><h2>审核清单</h2><div class="review-list">${['来源能支持所写的范围','材料、玩法与停止条件清楚','不把阶段建议写成发育考核','原创与授权边界、英语意思已核对'].map((t,i)=>`<label class="checkbox-label"><input type="checkbox" data-check="${i}" ${state.admin.checks.includes(i)?'checked':''} ${role!=='reviewer'||state.admin.status!=='review'?'disabled':''}><span>${t}</span></label>`).join('')}</div><div class="button-row" style="margin-top:24px"><button class="secondary" data-action="reject-review" ${role!=='reviewer'||state.admin.status!=='review'?'disabled':''}>退回修改</button><button class="primary" data-action="approve-review" ${role!=='reviewer'||state.admin.status!=='review'?'disabled':''}>通过审核</button></div><p class="field-help">本页角色切换仅供演示，不等于真实独立审阅。发布者也不能跳过审核。</p>${state.admin.status==='approved'?'<button class="text-button block-button" data-action="go" data-path="releases">查看发布前确认 →</button>':''}</section></div>`;}
  function releasesView(){return `<div class="desktop-title"><div><h1>让好内容，稳稳地更新。</h1><p>已开展和已记录的历史不会被普通修订覆盖。</p></div></div><div class="release-step"><span>01 草稿</span><span>02 审核</span><span>03 发布</span><span>04 撤回与留档</span></div><section class="review-card" style="max-width:900px"><span class="pill">${adminStatus()}</span><h2 style="margin-top:15px">${esc(state.admin.title)}</h2><p class="small muted">只发布一个示例修订，生成新的不可变版本。不会把其他23张草稿一并发布。</p><div class="notice-card"><strong>发布影响</strong><br>用于之后生成的合格安排；已开始、已记录和家长锁定项保留。安全撤回单独处理，会阻断未开展玩法并提供替换。</div><div class="button-row"><button class="primary" data-action="publish" ${role!=='publisher'||state.admin.status!=='approved'?'disabled':''}>核对并发布</button><button class="secondary" data-action="withdraw" ${role!=='publisher'||state.admin.status!=='published'?'disabled':''}>撤回这个版本</button></div><p class="field-help">需要发布角色和已通过审核的草稿。这里只模拟发布，不改变真实内容库。</p></section><div class="section-title"><h2>发布记录</h2></div>${state.admin.releases.length?state.admin.releases.map(r=>`<div class="source-row"><div><h3>${esc(r.action)} · 演示版本${r.version}</h3><p>${esc(r.note)}</p></div><span class="pill neutral">本机模拟</span></div>`).join(''):empty('还没有发布记录','把示例卡保存、送审、通过，再由发布角色完成演示。')}`;}
  function sourcesView(){return `<div class="desktop-title"><div><h1>知道内容从哪里来。</h1><p>已联网核验的依据与适用范围；不将来源引用当成活动认证。</p></div></div>${content.sources.map(s=>`<div class="source-row"><div><h3>${esc(s.title)}</h3><p>${esc(s.scope)} · 核验${s.verifiedOn}</p></div><a class="text-button" href="${s.url}" target="_blank" rel="noopener noreferrer">查看来源 ${icon('arrow-up-right')}</a></div>`).join('')}`;}
  function render(){
    const [page,id,itemId]=route();let body,current=page;
    if(page==='activity'&&itemId&&itemById(itemId))day=itemById(itemId).dayIndex;
    if(surface==='admin'){
      if(page==='editor'){body=adminEditor();current='library';}else if(page==='review')body=reviewView();else if(page==='releases')body=releasesView();else if(page==='sources')body=sourcesView();else if(page==='activity'){body=detailView(id);current='library';}else{body=adminLibrary();current='library';}
      app.innerHTML=desktopShell(body,current);
    }else{
      switch(page){
        case 'activity':body=detailView(id,itemId);current=itemId?'today':'discover';break;
        case 'discover':body=discoverView();break;
        case 'books':body=title('家里的书，都有新玩法','不必买新的，先从熟悉的一页开始。')+booksView();break;
        case 'stage':body=stageView();break;
        case 'growth':body=memoriesView();break;
        case 'measurements':body=measurementsView();current='growth';break;
        case 'settings':body=settingsView();break;
        case 'week':body=weekView();current='today';break;
        case 'start':body=startView();break;
        default:body=surface==='parent'?parentToday():todayView();current='today';
      }
      if(surface==='parent'&&page==='week')body=`<div class="button-row" style="justify-content:flex-end;margin-bottom:24px"><button style="flex:0 1 auto" class="secondary" data-action="print">${icon('printer')}打印这一周</button><button style="flex:0 1 auto" class="secondary" data-action="export">${icon('download')}导出演示记录</button></div>`+body;
      if(state.conflictDraft){body=`<div class="status-note">${icon('git-merge')}一条记录还在等待选择。<button class="text-button" data-action="resume-conflict">继续处理</button></div>`+body;}
      app.innerHTML=surface==='mobile'?mobileShell(body,current):desktopShell(body,current==='discover'?'books':current);
    }
    icons();bindPage();
  }
  function bindPage(){
    $('#activity-search')?.addEventListener('input',e=>{query=e.target.value;$('#library-results').innerHTML=libraryCards();icons();});
    $('#admin-role')?.addEventListener('change',e=>{role=e.target.value;render();});
    const editor=$('#admin-editor');
    if(editor){editor.addEventListener('submit',e=>{e.preventDefault();if(saveAdminForm())toast('草稿已保存在本机，仍需重新审核。');});editor.addEventListener('input',()=>{$('#draft-preview-title').textContent=editor.elements.title.value;$('#draft-preview-opening').textContent='“'+editor.elements.opening.value+'”';});}
    document.querySelectorAll('[data-check]').forEach(el=>el.addEventListener('change',()=>{if(role!=='reviewer'||state.admin.status!=='review')return;commit(s=>{s.admin.checks=[...document.querySelectorAll('[data-check]:checked')].map(x=>+x.dataset.check);});}));
  }
  function saveAdminForm(){if(role!=='editor')return false;const form=$('#admin-editor');if(!form?.reportValidity())return false;return commit(s=>{s.admin.title=form.elements.title.value.trim();s.admin.opening=form.elements.opening.value.trim();s.admin.note=form.elements.note.value.trim();s.admin.status='draft';s.admin.checks=[];});}
  function openRecord(id,cardId,status='played'){
    if(id&&itemById(id)?.dayIndex>0){toast('未来的安排还不能记录。');return;}
    const existing=state.records[id],c=cards[cardId]||cards[itemById(id)?.cardId]||cards.roll;
    sheet(existing?'这次陪伴，留下了什么？':'一起玩过，就很好。',`<p class="sheet-subtitle">${esc(c.title)} · 不用填满时长，也不用写很多。</p><form class="form-grid" id="record-form"><label><span>这次的状态</span><select name="status"><option value="played" ${(existing?.status||status)==='played'?'selected':''}>一起玩了</option><option value="skipped" ${(existing?.status||status)==='skipped'?'selected':''}>今天先跳过</option></select></label><div><span class="small">谁陪着玩？</span><div class="check-pills" style="margin-top:8px">${[['me','我'],['partner','另一位家长']].map(([value,label])=>`<label><input type="checkbox" name="participants" value="${value}" ${(existing?.participants||[member]).includes(value)?'checked':''}>${label}</label>`).join('')}</div></div><label><span>想记的一句话 <span class="muted">（选填）</span></span><textarea name="note" maxlength="600" placeholder="比如：很喜欢把球滚回来，还想再来。">${esc(existing?.note||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="again" ${existing?.again?'checked':''}><span>下次还想再玩</span></label><p class="field-help">记录者：${member==='me'?'我':'另一位家长'} · 陪伴者可以不同</p><p class="form-error" role="alert"></p><div class="sheet-footer"><button class="secondary" type="button" data-action="close">先不记</button><button class="primary" type="submit">${icon('check')}保存这次陪伴</button></div></form>`,(data,form)=>{
      const participants=data.getAll('participants');if(data.get('status')==='played'&&!participants.length){$('.form-error',form).textContent='选一位实际陪伴者，或选择今天先跳过。';return;}
      const record={status:data.get('status'),participants,note:data.get('note').trim(),again:data.has('again'),author:member,date:today,cardId:c.id,sync:scenario==='offline'?'pending':'local_demo'};
      const key=id||'session-'+crypto.randomUUID();
      if(scenario==='conflict'){conflictSheet(key,record);return;}
      if(commit(s=>{s.records[key]=record;})){closeSheet();render();toast(scenario==='offline'?'已存本机，联网后待同步（演示）。':'已记下这次陪伴，仅保存在本机演示。');}
    });
  }
  function conflictSheet(id,record){const remote={...record,note:'另一位家长的示例：先看着球，后来愿意摸一摸。',participants:['partner']};sheet('另一位家长也更新了记录',`<p class="sheet-subtitle">两份内容都在，选择怎样保留。这是冲突场景模拟。</p><div class="conflict-grid"><section><strong>我刚刚记的</strong><p>${esc(record.note||'没有文字备注')}</p></section><section><strong>另一位家长的</strong><p>${esc(remote.note)}</p></section></div><div class="form-grid"><button class="primary" data-merge="both">保留双方文字与陪伴者</button><button class="secondary" data-merge="mine">采用我这一份</button><button class="secondary" data-merge="theirs">采用另一份</button><button class="text-button" data-action="close">稍后决定，先保留草稿</button></div>`);
    // 本机草稿独立保存，取消不会丢掉冲突双方。
    commit(s=>{s.conflictDraft={id,mine:record,theirs:remote};});
    dialog.querySelectorAll('[data-merge]').forEach(btn=>btn.addEventListener('click',()=>{const mode=btn.dataset.merge;const result=mode==='mine'?record:mode==='theirs'?remote:{...record,note:`我：${record.note||'已一起玩'}\n另一位家长：${remote.note}`,participants:[...new Set([...record.participants,...remote.participants])]};if(commit(s=>{s.records[id]=result;delete s.conflictDraft;})){scenario='normal';$('#scenario').value='normal';closeSheet();render();toast('已按选择保留，本机演示记录已更新。');}}));
  }
  function replaceSheet(id){const item=itemById(id);if(!item)return;if(state.records[id]){toast('这项已经有记录。想再玩时，请从发现中选择临时活动。');return;}const alternatives=content.cards.filter(c=>c.kind===item.kind&&c.id!==item.cardId&&!c.withdrawn);sheet('换个同样好开始的玩法',`<p class="sheet-subtitle">只替换这一项，保留原来的时段和预算。</p><div class="library-list">${alternatives.map(c=>`<button class="library-card" data-replace="${c.id}">${thumbnail(c)}<span class="card-copy"><h3>${c.title}</h3><p>${esc(c.materials.join(' · ')||'不用道具')}</p></span>${icon('arrow-right')}</button>`).join('')}</div>`);dialog.querySelectorAll('[data-replace]').forEach(btn=>btn.addEventListener('click',()=>{if(commit(s=>{s.replacements[id]=btn.dataset.replace;})){closeSheet();go('today');render();toast('这一项已换好，其余安排保留。');}}));}
  function modeSheet(){const lite=state.modes[day]==='lite';sheet(lite?'恢复完整的陪伴灵感？':'今天轻松一点，也很好。',`<p class="sheet-subtitle">${lite?'重新展示尚未开始的六项灵感，已经留下的记录保留。':'保留共读、运动、探索和英语，每项约5分钟。已经记录的内容保留，其余未开始项暂时收起。'}</p><div class="notice-card">${lite?'约60分钟，仍可拆分或只选一项。':'未开始的内容按每项约5分钟安排；已有记录保留原预算，显示合计可能超过20分钟。随时可恢复。'}</div><div class="sheet-footer"><button class="secondary" data-action="close">保持现在</button><button class="primary" id="confirm-mode">${lite?'恢复完整安排':'换成轻松一天'}</button></div>`);$('#confirm-mode').addEventListener('click',()=>{if(commit(s=>{s.modes[day]=lite?'standard':'lite';})){closeSheet();render();toast('只调整未开始项，已有记录已保留。');}});}
  function memorySheet(id){const old=state.memories.find(m=>m.id===id);sheet(old?'编辑这个小瞬间':'记一个小瞬间',`<p class="sheet-subtitle">写给以后的你们看。没有标准答案。</p><form class="form-grid"><label><span>记录哪一种</span><select name="type">${[['quote','孩子原话'],['story','小故事'],['first','第一次']].map(([v,l])=>`<option value="${v}" ${old?.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label><span>发生日期</span><input type="date" name="date" required max="${today}" value="${old?.date||today}"></label><label><span>想留下的内容</span><textarea name="text" maxlength="2000" required placeholder="今天，宝宝…">${esc(old?.text||'')}</textarea></label><label class="checkbox-label"><input name="first" type="checkbox" ${old?.type==='first'?'checked':''}><span>如果是第一次，我确认这次是第一次</span></label><label class="checkbox-label"><input name="photo" type="checkbox" ${old?.photo?'checked':''}><span>加入照片占位示例（不读取相册、不上传）</span></label><p class="form-error" role="alert"></p><div class="sheet-footer"><button class="secondary" type="button" data-action="close">取消</button><button class="primary" type="submit">保存小瞬间</button></div></form>`,(data,form)=>{if(data.get('type')==='first'&&!data.has('first')){$('.form-error',form).textContent='请由家长确认第一次，或者改成小故事。';return;}if(!data.get('text').trim()){$('.form-error',form).textContent='写下一点想留下的内容。';return;}const m={id:old?.id||crypto.randomUUID(),type:data.get('type'),date:data.get('date'),text:data.get('text').trim(),photo:data.has('photo'),author:member==='me'?'我':'另一位家长'};if(commit(s=>{s.memories=s.memories.filter(x=>x.id!==m.id);s.memories.unshift(m);})){closeSheet();go('growth');render();toast(m.photo?'文字已保存；照片只是未上传的占位示例。':'小瞬间已保存在当前浏览器。');}});const form=$('form',dialog);form.dataset.initial=new URLSearchParams(new FormData(form)).toString();form.dataset.guard='true';}
  function measurementSheet(){sheet('添加一次真实测量',`<p class="sheet-subtitle">原型只验证输入与展示；不作健康判断。</p><form class="form-grid"><label><span>测量日期</span><input type="date" name="date" required value="${today}" max="${today}"></label><label><span>测量类型</span><select name="kind" id="measure-kind"><option value="height">身长 / 身高（cm）</option><option value="weight">体重（kg）</option></select></label><label><span>测量数值</span><input type="number" name="value" required min="0.1" max="300" step="0.1" inputmode="decimal" placeholder="请填写测量值"></label><label><span>测量方式</span><select name="method" id="measure-method"><option>卧位身长</option><option>站立身高</option></select></label><label><span>来源</span><select name="source"><option>家中测量</option><option>儿保记录</option></select></label><div class="sheet-footer"><button class="secondary" type="button" data-action="close">取消</button><button class="primary" type="submit">保存测量</button></div></form>`,data=>{if(commit(s=>{s.measurements.unshift({id:crypto.randomUUID(),date:data.get('date'),kind:data.get('kind'),value:+data.get('value'),method:data.get('method'),source:data.get('source')});})){closeSheet();go('measurements');render();toast('已保存测量事实，未生成医学解释。');}});$('#measure-kind').addEventListener('change',e=>{$('#measure-method').innerHTML=e.target.value==='weight'?'<option>体重秤</option>':'<option>卧位身长</option><option>站立身高</option>';});}
  function exportSheet(){sheet('导出当前演示记录',`<p class="sheet-subtitle">只导出本浏览器保存的虚构数据。可保存一份JSON供查看，不包含真实家庭资料。</p><div class="notice-card">${state.memories.filter(m=>m.photo).length}张照片占位没有上传，将在遗漏清单中列出。正式产品还支持日期范围、CSV与已上传媒体ZIP。</div><div class="sheet-footer"><button class="secondary" data-action="close">取消</button><button class="primary" id="download-json">下载演示记录</button></div>`);$('#download-json').addEventListener('click',()=>{const data={kind:'babyplan-design-demo',exportedOn:today,records:state.records,memories:state.memories,measurements:state.measurements,missingMedia:state.memories.filter(m=>m.photo).map(m=>({memoryId:m.id,reason:'prototype_placeholder_not_uploaded'}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='BabyPlan-演示记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeSheet();toast('已生成演示记录文件。');});}

  document.addEventListener('click',e=>{
    const el=e.target.closest('[data-action]');if(!el)return;
    const a=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
    if(a==='close'){const f=$('form[data-guard]',dialog);if(f&&f.dataset.initial!==new URLSearchParams(new FormData(f)).toString()){if(!window.confirm('还有没保存的文字。确定放弃这次修改吗？'))return;}closeSheet();}
    else if(a==='go')go(el.dataset.path);
    else if(a==='day'){day=+value;selectedItem=null;go('today');render();}
    else if(a==='retry'){scenario='normal';$('#scenario').value='normal';render();}
    else if(a==='discover')go('discover');
    else if(a==='open-item'){const item=itemById(id);if(surface==='parent'){selectedItem=id;render();}else go(`activity/${item.cardId}/${id}`);}
    else if(a==='open-card')go('activity/'+el.dataset.card);
    else if(a==='record'||a==='skip')openRecord(id,el.dataset.card,a==='skip'?'skipped':'played');
    else if(a==='replace')replaceSheet(id);
    else if(a==='mode')modeSheet();
    else if(a==='resume-conflict'&&state.conflictDraft)conflictSheet(state.conflictDraft.id,state.conflictDraft.mine);
    else if(a==='library-tab'){libraryTab=value;render();}
    else if(a==='filter'){filter=value;render();}
    else if(a==='stage-band'){stage=value;render();}
    else if(a==='memory-filter'){memoryFilter=value;render();}
    else if(a==='memory')memorySheet(id);
    else if(a==='measurement')measurementSheet();
    else if(a==='book'){const b=content.books.find(x=>x.id===id);sheet(b.title,`<p class="sheet-subtitle">${b.note}。本原型不提供受保护书页，也不推定点读兼容。</p><form class="form-grid"><label><span>家里的这本书，想记什么？</span><textarea name="note" maxlength="300" placeholder="比如：最喜欢有小狗的那一页">${esc(state.bookNotes[id]||'')}</textarea></label><p class="field-help">这里只改家庭备注，不会将版本自动标记为核验通过。</p><button class="primary" type="submit">保存备注</button></form>`,data=>{if(commit(s=>{s.bookNotes[id]=data.get('note').trim();})){closeSheet();render();toast('书架备注已保存在本机。');}});}
    else if(a==='focus'){const guide=content.stageGuides.find(g=>g.focuses.some(f=>f.id===id)),f=guide.focuses.find(x=>x.id===id),s=content.sources.find(x=>x.id===guide.sourceId);sheet(f.title,`<p class="sheet-subtitle">${f.everyday}</p><div class="material-box"><h3>你可以这样支持</h3><p>${f.support}</p></div><p class="small"><strong>更容易：</strong>${f.easier}</p><p class="small" style="margin-top:12px"><strong>愿意时下一步：</strong>${f.next}</p>${f.cardIds.length?`<div class="chips">${f.cardIds.map(c=>`<button class="secondary" data-focus-card="${c}">${cards[c].title} →</button>`).join('')}</div>`:'<p class="field-help">这个阶段的专门活动包还在准备；不把18月龄卡自动当成下一阶段课程。</p>'}<label style="margin-top:20px"><span>记一次家庭观察（选填）</span><select id="observation"><option value="">暂时不记</option>观察到过</option><option>还没留意</option><option>想和专业人员聊聊</option></select></label><button class="primary block-button" id="save-observation" style="margin-top:16px">保存观察</button><p class="field-help" style="margin-top:15px">依据${guide.sourceAgeMonths}月节点转译，不是整个区间的达标表。<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a></p>`);$('#observation').value=state.observations[id]||'';$('#save-observation').onclick=()=>{if(commit(next=>{next.observations[id]=$('#observation').value;})){closeSheet();render();toast('只记下这次观察，不计算发育分数。');}};dialog.querySelectorAll('[data-focus-card]').forEach(b=>b.onclick=()=>{closeSheet();go('activity/'+b.dataset.focusCard);});}
    else if(a==='concern')sheet('把具体观察带去聊聊',`<p class="sheet-subtitle">如果出现曾经会的能力倒退、相应年龄节点尚未出现，或你持续担心，可以联系儿保 / 儿科人员讨论。</p><div class="material-box"><h3>可以先记下来</h3><p>什么时候注意到、在什么情境发生、最近有无变化。无需用活动次数证明问题或推算诊断。</p></div><a class="text-button" href="https://www.cdc.gov/act-early/milestones/18-months.html" target="_blank" rel="noopener noreferrer">查看CDC来源说明 ↗</a><button class="primary block-button" data-action="close">知道了</button>`);
    else if(a==='reminder')sheet('给陪伴留一个轻轻的提醒',`<p class="sheet-subtitle">建议16:00附近，每台指定设备每天最多一次。这个原型不会发送系统通知。</p><form class="form-grid"><label class="checkbox-label"><input name="enabled" type="checkbox" ${state.reminder?'checked':''}><span>保存开启提醒的偏好</span></label><label><span>希望提醒的时间</span><input name="time" type="time" value="${state.reminderTime}" required></label><p class="field-help">正式App会在开启时申请权限；系统省电可能延迟。当天20:00以后不追发。</p><button class="primary" type="submit">保存偏好</button></form>`,data=>{if(commit(s=>{s.reminder=data.has('enabled');s.reminderTime=data.get('time');})){closeSheet();render();toast('已保存演示偏好，未创建系统提醒。');}});
    else if(a==='invite')sheet('邀请另一位家长',`<p class="sheet-subtitle">正式产品使用一次性邀请，24小时失效。加入后可查看本家庭的安排与成长资料。</p><div class="notice-card">这里是邀请设计示例，没有连接账号服务，不能生成可用邀请。</div><button class="primary block-button" data-action="close">了解加入方式</button>`);
    else if(a==='age')sheet('按现在的阶段开始',`<p class="sheet-subtitle">演示孩子为18～23月龄，未填写生日。正式App可录入当前月龄和基准日，也可自愿填写生日。</p><div class="notice-card">估算月龄不用于精确百分位。下个阶段有经过审核的内容后，再提供适用玩法。</div><button class="primary block-button" data-action="close">知道了</button>`);
    else if(a==='schedule-info')sheet('让安排适应家里的节奏',`<p class="sheet-subtitle">晚饭前约25分钟、晚饭后约25分钟、睡前约10分钟。每段可拆开，也可以只玩一项。</p><div class="notice-card">睡前不假定具体钟点，周末不自动加量。时长是设计预算，不是训练要求。</div><button class="primary block-button" data-action="close">按自己的节奏来</button>`);
    else if(a==='about')sheet('这是可以试点的设计',`<p class="sheet-subtitle">你看到的是BabyPlan v2交互原型，固定演示日为2026年11月13日。资料来自项目需求与原创内容候选。</p><p class="small muted">保存仅写入当前浏览器。尚未实现原生App、真实家庭同步、系统提醒、照片上传与服务部署。</p><button class="primary block-button" style="margin-top:22px" data-action="close">继续看看</button>`);
    else if(a==='export')exportSheet();
    else if(a==='print')window.print();
    else if(a==='submit-review'){if(role!=='editor'||!saveAdminForm())return;if(commit(s=>{s.admin.status='review';s.admin.checks=[];})){toast('示例草稿已送审；请切换为内容审阅角色继续。');go('review');}}
    else if(a==='approve-review'){if(role!=='reviewer'||state.admin.status!=='review')return;if(state.admin.checks.length!==4){toast('请逐项核对四项审核内容。');return;}if(commit(s=>{s.admin.status='approved';})){render();toast('审核通过（模拟）。仍需发布角色确认发布。');}}
    else if(a==='reject-review'){if(role!=='reviewer'||state.admin.status!=='review')return;sheet('退回修改',`<form class="form-grid"><label><span>说明需要修改什么</span><textarea required name="reason" maxlength="500"></textarea></label><button class="primary" type="submit">退回给编辑</button></form>`,data=>{if(!data.get('reason').trim())return;if(commit(s=>{s.admin.status='draft';s.admin.note='审核退回：'+data.get('reason');s.admin.checks=[];})){closeSheet();render();toast('已退回，本机保留退回原因。');}});}
    else if(a==='publish'){if(role!=='publisher'||state.admin.status!=='approved')return;sheet('确认发布这个示例版本？',`<p class="sheet-subtitle">${esc(state.admin.title)} · 仅一个示例活动修订</p><div class="notice-card">只影响之后可采用新内容的安排，历史记录与锁定项保留。此按钮只改变本机演示状态。</div><div class="sheet-footer"><button class="secondary" data-action="close">取消</button><button class="primary" id="confirm-publish">确认模拟发布</button></div>`);$('#confirm-publish').onclick=()=>{if(commit(s=>{s.admin.status='published';s.admin.releases.unshift({action:'发布',version:s.admin.releases.filter(r=>r.action==='发布').length+1,note:'原创候选的工作流演示，不代表已完成真实内容审阅。'});})){closeSheet();render();toast('发布流程演示完成，未修改任何真实服务。');}};}
    else if(a==='withdraw'){if(role!=='publisher'||state.admin.status!=='published')return;sheet('撤回这个示例版本',`<p class="sheet-subtitle">安全撤回会阻断继续推荐，并保留历史记录供追溯。</p><form class="form-grid"><label><span>撤回原因</span><textarea required name="reason" maxlength="500" placeholder="请写明需要停止推荐的原因"></textarea></label><button class="danger" type="submit">确认模拟撤回</button></form>`,data=>{if(!data.get('reason').trim())return;if(commit(s=>{s.admin.status='withdrawn';s.admin.releases.unshift({action:'撤回',version:s.admin.releases.filter(r=>r.action==='发布').length,note:data.get('reason')});})){closeSheet();render();toast('已模拟撤回，历史仍保留。');}});}
  });
  dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const controls=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')].filter(x=>x.getClientRects().length);const first=controls[0],last=controls.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
  dialog.addEventListener('cancel',e=>{const form=$('form[data-guard]',dialog);if(form&&form.dataset.initial!==new URLSearchParams(new FormData(form)).toString()){e.preventDefault();if(window.confirm('还有没保存的文字。确定放弃这次修改吗？'))closeSheet();}});
  $('#review-toggle').addEventListener('click',()=>{const p=$('#review-options');p.hidden=!p.hidden;$('#review-toggle').setAttribute('aria-expanded',String(!p.hidden));});
  $('#scenario').addEventListener('change',e=>{scenario=e.target.value;render();});
  $('#theme').addEventListener('change',e=>document.documentElement.dataset.theme=e.target.value);
  $('#font-scale').addEventListener('change',e=>document.documentElement.style.setProperty('--font-scale',e.target.value));
  $('#member').addEventListener('change',e=>{member=e.target.value;render();});
  $('#reset-demo').addEventListener('click',()=>sheet('重置本机的演示记录？',`<p class="sheet-subtitle">将清除本原型中新增的记录、测量与草稿，恢复虚构示例。不会影响旧版原型或其他项目。</p><div class="sheet-footer"><button class="secondary" data-action="close">取消</button><button class="danger" id="confirm-reset">确认重置</button></div>`));
  dialog.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){try{localStorage.removeItem(storageKey);state=initial();day=0;closeSheet();render();toast('本机演示已重置。');}catch(_){toast('未能清除演示存储。');}}});
  window.addEventListener('hashchange',()=>{render();app.scrollTop=0;window.scrollTo(0,0);});
  window.addEventListener('storage',e=>{if(e.key===storageKey){try{state=JSON.parse(e.newValue)||initial();render();}catch(_){}}});
  // 仅供自动化检查访问派生状态，不代表真实API。
  window.BabyPlanDemo={getState:()=>structuredClone(state),getDayItems:()=>dayItems(),render};
  render();
})();
